import React, { useState, useEffect } from 'react';
import { Wallet, Key, Shield, CheckCircle, XCircle, AlertCircle } from 'lucide-react';

const App = () => {
  const [wallets, setWallets] = useState([]);
  const [did, setDid] = useState('');
  const [quorum, setQuorum] = useState(2);
  const [step, setStep] = useState('setup'); // setup, register, login, authenticated
  const [challenge, setChallenge] = useState('');
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const API_URL = 'http://localhost:3000';

  // Générer des wallets Ethereum
  const generateWallets = async () => {
    setLoading(true);
    setError('');
    try {
      // Simuler la génération de wallets (en production, utiliser ethers.js)
      const mockWallets = Array.from({ length: 3 }, (_, i) => ({
        id: `key${i + 1}`,
        address: `0x${Math.random().toString(16).substr(2, 40)}`,
        privateKey: `0x${Math.random().toString(16).substr(2, 64)}`
      }));

      setWallets(mockWallets);
      setDid(`did:eth:${mockWallets[0].address}`);
      setMessage('✅ 3 wallets générés avec succès');
    } catch (err) {
      setError('Erreur lors de la génération des wallets');
    }
    setLoading(false);
  };

  // Enregistrer le DID
  const registerDID = async () => {
    if (wallets.length === 0) {
      setError('Générez d\'abord des wallets');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const response = await fetch(`${API_URL}/auth/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          did,
          publicKeys: wallets.map(w => ({ id: w.id, key: w.address })),
          quorum
        })
      });

      const data = await response.json();

      if (response.ok) {
        setMessage(data.message);
        setStep('login');
      } else {
        setError(data.error || 'Erreur lors de l\'enregistrement');
      }
    } catch (err) {
      setError('Impossible de contacter le serveur');
    }
    setLoading(false);
  };

  // Demander un challenge
  const requestChallenge = async () => {
    setLoading(true);
    setError('');

    try {
      const response = await fetch(`${API_URL}/auth/challenge/${encodeURIComponent(did)}`);
      const data = await response.json();

      if (response.ok) {
        setChallenge(data.challenge);
        setMessage(`Challenge reçu: ${data.challenge.substring(0, 20)}...`);
      } else {
        setError(data.error || 'DID non trouvé');
      }
    } catch (err) {
      setError('Impossible de contacter le serveur');
    }
    setLoading(false);
  };

  // Signer et vérifier
  const signAndVerify = async () => {
    if (!challenge) {
      setError('Demandez d\'abord un challenge');
      return;
    }

    setLoading(true);
    setError('');

    try {
      // Simuler la signature (en production, utiliser ethers.js pour signer)
      const signatures = wallets.slice(0, quorum).map(wallet => ({
        keyId: wallet.id,
        signature: `0x${Math.random().toString(16).substr(2, 130)}` // Mock signature
      }));

      const response = await fetch(`${API_URL}/auth/verify`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          did,
          signatures
        })
      });

      const data = await response.json();

      if (response.ok && data.authenticated) {
        setMessage(`🎉 Authentifié! ${data.message}`);
        setStep('authenticated');
      } else {
        setError(data.reason || 'Authentification échouée');
      }
    } catch (err) {
      setError('Erreur lors de la vérification');
    }
    setLoading(false);
  };

  const reset = () => {
    setStep('setup');
    setWallets([]);
    setChallenge('');
    setMessage('');
    setError('');
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 p-8">
      <div className="max-w-4xl mx-auto">
        <div className="bg-white rounded-2xl shadow-xl p-8">
          {/* Header */}
          <div className="flex items-center gap-4 mb-8">
            <Shield className="w-12 h-12 text-indigo-600" />
            <div>
              <h1 className="text-3xl font-bold text-gray-800">DID Authentication</h1>
              <p className="text-gray-600">Multi-signature blockchain identity</p>
            </div>
          </div>

          {/* Messages */}
          {message && (
            <div className="mb-6 p-4 bg-green-50 border border-green-200 rounded-lg flex items-start gap-3">
              <CheckCircle className="w-5 h-5 text-green-600 flex-shrink-0 mt-0.5" />
              <p className="text-green-800">{message}</p>
            </div>
          )}

          {error && (
            <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg flex items-start gap-3">
              <XCircle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
              <p className="text-red-800">{error}</p>
            </div>
          )}

          {/* Step 1: Setup */}
          {step === 'setup' && (
            <div className="space-y-6">
              <div>
                <h2 className="text-xl font-semibold mb-4 flex items-center gap-2">
                  <Key className="w-6 h-6" />
                  Étape 1: Génération des wallets
                </h2>
                <p className="text-gray-600 mb-4">
                  Générez 3 wallets Ethereum qui serviront de clés pour votre identité décentralisée.
                </p>
                <button
                  onClick={generateWallets}
                  disabled={loading}
                  className="px-6 py-3 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:bg-gray-400 transition-colors"
                >
                  {loading ? 'Génération...' : 'Générer les wallets'}
                </button>
              </div>

              {wallets.length > 0 && (
                <div className="space-y-4">
                  <h3 className="font-semibold text-gray-700">Wallets générés:</h3>
                  {wallets.map((wallet, i) => (
                    <div key={i} className="p-4 bg-gray-50 rounded-lg border border-gray-200">
                      <div className="flex items-center gap-2 mb-2">
                        <Wallet className="w-4 h-4 text-indigo-600" />
                        <span className="font-mono text-sm font-semibold">{wallet.id}</span>
                      </div>
                      <p className="text-xs font-mono text-gray-600 break-all">{wallet.address}</p>
                    </div>
                  ))}

                  <div className="pt-4 border-t border-gray-200">
                    <label className="block mb-2 font-semibold text-gray-700">
                      Quorum requis (signatures nécessaires):
                    </label>
                    <input
                      type="number"
                      min="1"
                      max="3"
                      value={quorum}
                      onChange={(e) => setQuorum(parseInt(e.target.value))}
                      className="w-32 px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent"
                    />
                    <p className="text-sm text-gray-500 mt-2">
                      {quorum} signature(s) sur 3 seront nécessaires pour s'authentifier
                    </p>
                  </div>

                  <button
                    onClick={() => setStep('register')}
                    className="w-full px-6 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors"
                  >
                    Continuer vers l'enregistrement
                  </button>
                </div>
              )}
            </div>
          )}

          {/* Step 2: Register */}
          {step === 'register' && (
            <div className="space-y-6">
              <div>
                <h2 className="text-xl font-semibold mb-4">Étape 2: Enregistrement du DID</h2>
                <div className="p-4 bg-blue-50 border border-blue-200 rounded-lg mb-4">
                  <p className="font-mono text-sm break-all">{did}</p>
                </div>
                <p className="text-gray-600 mb-4">
                  Enregistrez votre identité décentralisée avec vos {wallets.length} clés publiques.
                </p>
                <button
                  onClick={registerDID}
                  disabled={loading}
                  className="px-6 py-3 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:bg-gray-400 transition-colors"
                >
                  {loading ? 'Enregistrement...' : 'Enregistrer le DID'}
                </button>
              </div>
            </div>
          )}

          {/* Step 3: Login */}
          {step === 'login' && (
            <div className="space-y-6">
              <div>
                <h2 className="text-xl font-semibold mb-4">Étape 3: Authentification</h2>
                <div className="space-y-4">
                  {!challenge ? (
                    <button
                      onClick={requestChallenge}
                      disabled={loading}
                      className="px-6 py-3 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:bg-gray-400 transition-colors"
                    >
                      {loading ? 'Demande...' : 'Demander un challenge'}
                    </button>
                  ) : (
                    <>
                      <div className="p-4 bg-yellow-50 border border-yellow-200 rounded-lg">
                        <p className="text-sm font-semibold mb-2">Challenge à signer:</p>
                        <p className="font-mono text-xs break-all">{challenge}</p>
                      </div>
                      <button
                        onClick={signAndVerify}
                        disabled={loading}
                        className="px-6 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 disabled:bg-gray-400 transition-colors"
                      >
                        {loading ? 'Vérification...' : `Signer avec ${quorum} clé(s) et vérifier`}
                      </button>
                    </>
                  )}
                </div>
              </div>
            </div>
          )}

          {/* Step 4: Authenticated */}
          {step === 'authenticated' && (
            <div className="text-center space-y-6">
              <div className="inline-flex items-center justify-center w-20 h-20 bg-green-100 rounded-full mb-4">
                <CheckCircle className="w-12 h-12 text-green-600" />
              </div>
              <h2 className="text-2xl font-bold text-gray-800">Authentification réussie!</h2>
              <p className="text-gray-600">Votre identité décentralisée a été vérifiée.</p>
              <button
                onClick={reset}
                className="px-6 py-3 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors"
              >
                Recommencer
              </button>
            </div>
          )}

          {/* Info Box */}
          <div className="mt-8 p-4 bg-gray-50 border border-gray-200 rounded-lg">
            <div className="flex items-start gap-3">
              <AlertCircle className="w-5 h-5 text-gray-600 flex-shrink-0 mt-0.5" />
              <div className="text-sm text-gray-600">
                <p className="font-semibold mb-1">Note de développement:</p>
                <p>Cette démo utilise des signatures simulées. En production, intégrez ethers.js ou web3.js pour générer de vraies clés et signatures Ethereum.</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;
